cat > candidate.mjs <<'EOF'
let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const respond = (status, body, o = {}) => ({
  http: { status, headers: json, body },
  database: {
    accounts: o.accounts ?? [],
    transaction: { committed: o.committed ?? false, rolledBack: !(o.committed ?? false) && o.accounts !== undefined }
  },
  messages: o.messages ?? [],
  ordering: o.ordering ?? [],
  failures: o.failures ?? [],
  retryability: o.retryable ?? false
});

const { transferId, idempotencyKey, fromId, toId, fromBalance, toBalance, amount, fromVersion, toVersion } = input;
const unchanged = [
  { id: fromId, balance: fromBalance, version: fromVersion },
  { id: toId, balance: toBalance, version: toVersion }
];
const reject = (status, code, o = {}) =>
  respond(status, { error: code }, { accounts: unchanged, failures: [{ code, status }], ...o });

// Idempotency records: an array of prior {idempotencyKey, ...} or a single `replay`/`existingTransfer`.
const prior = [
  ...(Array.isArray(input.processedTransfers) ? input.processedTransfers : []),
  ...(Array.isArray(input.idempotencyRecords) ? input.idempotencyRecords : []),
  ...[input.replay, input.existingTransfer].filter((x) => x && typeof x === "object")
].find((r) => r && (r.idempotencyKey ?? r.key) === idempotencyKey && idempotencyKey !== undefined);

let out;
if (prior) {
  const body = prior.response ?? prior.body ?? {
    transferId: prior.transferId ?? transferId,
    fromBalance: prior.fromBalance ?? fromBalance,
    toBalance: prior.toBalance ?? toBalance
  };
  out = respond(prior.status ?? 200, body, {
    accounts: unchanged, committed: false, ordering: ["idempotency-check"]
  });
  out.database.transaction = { committed: false, rolledBack: false };
  out.http.headers = { ...json, "idempotent-replay": "true" };
} else if (!Number.isInteger(amount) || amount <= 0 || !Number.isFinite(fromBalance) || !Number.isFinite(toBalance) || fromId === toId) {
  out = reject(400, "invalid_request", { ordering: ["validate"] });
} else if (
  (input.expectedFromVersion !== undefined && input.expectedFromVersion !== fromVersion) ||
  (input.expectedToVersion !== undefined && input.expectedToVersion !== toVersion)
) {
  out = reject(409, "version_conflict", { ordering: ["validate", "version-check", "rollback"], retryable: true });
} else if (fromBalance < amount) {
  out = reject(422, "insufficient_funds", { ordering: ["validate", "version-check", "balance-check", "rollback"] });
} else {
  const newFrom = fromBalance - amount;
  const newTo = toBalance + amount;
  out = respond(200, { transferId, fromBalance: newFrom, toBalance: newTo }, {
    committed: true,
    accounts: [
      { id: fromId, balance: newFrom, version: fromVersion + 1 },
      { id: toId, balance: newTo, version: toVersion + 1 }
    ],
    messages: [{ type: "transfer.completed", transferId, fromId, toId, amount, idempotencyKey }],
    ordering: ["validate", "version-check", "balance-check", "update-accounts", "commit", "publish-event"]
  });
}

console.log(JSON.stringify(out));
EOF
